import React, { useState } from 'react';
import axios from 'axios';
import './SubmitRequestForm.css';

// Define the structure of a request item
interface RequestItem {
    componentType: string;
    quantity: number;
    notes: string;
}

const API_URL = 'http://localhost:3001'; // The URL of our backend service

const SubmitRequestForm = () => {
    const [patientName, setPatientName] = useState('');
    const [patientBloodType, setPatientBloodType] = useState('A+');
    const [urgency, setUrgency] = useState('Scheduled');
    const [items, setItems] = useState<RequestItem[]>([
        { componentType: 'Whole Blood', quantity: 1, notes: '' }
    ]);
    const [error, setError] = useState<string | null>(null);
    const [success, setSuccess] = useState<string | null>(null);

    const handleItemChange = (index: number, field: keyof RequestItem, value: string | number) => {
        const newItems = [...items];
        (newItems[index] as any)[field] = value;
        setItems(newItems);
    };

    const addItem = () => {
        setItems([...items, { componentType: 'Whole Blood', quantity: 1, notes: '' }]);
    };

    const removeItem = (index: number) => {
        const newItems = items.filter((_, i) => i !== index);
        setItems(newItems);
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError(null);
        setSuccess(null);

        // Basic validation
        if (!patientName.trim()) {
            setError('Patient name is required.');
            return;
        }

        const requestData = {
            // In a real app, these would come from the logged-in user's context
            hospitalId: 1, 
            staffId: 101,
            patientName,
            patientBloodType,
            urgency,
            items
        };

        try {
            const response = await axios.post(`${API_URL}/requests`, requestData);
            setSuccess(`Request submitted successfully! Request ID: ${response.data.requestId}`);
            // Reset form
            setPatientName('');
            setPatientBloodType('A+');
            setUrgency('Scheduled');
            setItems([{ componentType: 'Whole Blood', quantity: 1, notes: '' }]);
        } catch (err) {
            setError('Failed to submit request. Please check the console for details.');
            console.error(err);
        }
    };

    return (
        <form onSubmit={handleSubmit} className="request-form">
            {error && <div className="alert error">{error}</div>}
            {success && <div className="alert success">{success}</div>}

            <div className="form-group">
                <label>Patient Full Name</label>
                <input
                    type="text"
                    value={patientName}
                    onChange={(e) => setPatientName(e.target.value)}
                    placeholder="e.g., John Doe"
                    required
                />
            </div>

            <div className="form-group">
                <label>Patient Blood Type</label>
                <select value={patientBloodType} onChange={(e) => setPatientBloodType(e.target.value)}>
                    <option value="A+">A+</option>
                    <option value="A-">A-</option>
                    <option value="B+">B+</option>
                    <option value="B-">B-</option>
                    <option value="AB+">AB+</option>
                    <option value="AB-">AB-</option>
                    <option value="O+">O+</option>
                    <option value="O-">O-</option>
                </select>
            </div>

            <div className="form-group">
                <label>Urgency</label>
                <select value={urgency} onChange={(e) => setUrgency(e.target.value)}>
                    <option value="Scheduled">Scheduled</option>
                    <option value="Urgent">Urgent</option>
                    <option value="Emergency">Emergency</option>
                </select>
            </div>

            <fieldset>
                <legend>Required Items</legend>
                {items.map((item, index) => (
                    <div key={index} className="item-row">
                        <input
                            type="text"
                            value={item.componentType}
                            onChange={(e) => handleItemChange(index, 'componentType', e.target.value)}
                            placeholder="Component Type"
                        />
                        <input
                            type="number"
                            value={item.quantity}
                            onChange={(e) => handleItemChange(index, 'quantity', parseInt(e.target.value))}
                            min="1"
                        />
                        <input
                            type="text"
                            value={item.notes}
                            onChange={(e) => handleItemChange(index, 'notes', e.target.value)}
                            placeholder="Optional Notes"
                        />
                        <button type="button" className="remove-btn" onClick={() => removeItem(index)}>Remove</button>
                    </div>
                ))}
                <button type="button" className="add-btn" onClick={addItem}>Add Item</button>
            </fieldset>

            <button type="submit" className="submit-btn">Submit Request</button>
        </form>
    );
};

export default SubmitRequestForm;
